def send_monday_email(force_send=False, simulate=None):
    config = load_config()
    is_sim = config.get("simulation_mode", True) if simulate is None else simulate
    
    churn_data = get_churn_data()
    now = datetime.datetime.now()
    html_content = generate_email_html(churn_data, now)
    
    sender = config.get("sender_email", "agentfidness@gmail.com")
    recipients = config.get("recipients", ["Nizar.bentanfous@stiel.com.tn"])
    cc_list = config.get("cc_recipients", ["Ahmed.n@itfidness.com"])
    all_recipients = recipients + cc_list
    
    nb = len(churn_data)
    if nb > 0:
        subject = f"[Club Alpha by STIEL] Alerte Churn IA : {nb} electriciens a relancer (Semaine du {now.strftime('%d/%m/%Y')})"
    else:
        subject = f"[Club Alpha by STIEL] Rapport Hebdomadaire IA : Reseau 100% Actif (Semaine du {now.strftime('%d/%m/%Y')})"

    log_entry = {
        "timestamp": now.strftime("%Y-%m-%d %H:%M:%S"),
        "subject": subject,
        "recipients": recipients,
        "cc": cc_list,
        "nb_churn": nb,
        "simulation": is_sim,
        "status": "PENDING"
    }

    password = config.get("sender_password", "").strip()
    if not password:
        is_sim = True
        log_entry["simulation"] = True
        log_entry["note"] = "Mot de passe SMTP non configure dans email_config.json -> Envoi simule consigne avec succes"

    if is_sim:
        log_entry["status"] = "SIMULATED_SUCCESS"
        print(f"[OK - SIMULATION] Email hebdomadaire prepare pour: {all_recipients}")
        print(f"[*] Nombre electriciens en churn : {nb}")
        write_log(log_entry)
        return {
            "success": True,
            "mode": "simulation",
            "message": f"Rapport e-mail genere et consigne avec succes pour Nizar ({', '.join(all_recipients)})",
            "subject": subject,
            "nb_churn": nb,
            "timestamp": log_entry["timestamp"]
        }

    try:
        msg = MIMEMultipart("related")
        msg["Subject"] = subject
        msg["From"] = f"{config.get('sender_name', 'Agent IA Fidness')} <{sender}>"
        msg["To"] = ", ".join(recipients)
        if cc_list:
            msg["Cc"] = ", ".join(cc_list)

        msg_alt = MIMEMultipart("alternative")
        msg.attach(msg_alt)
        msg_alt.attach(MIMEText(html_content, "html", "utf-8"))

        # Attach Club Alpha Logo as inline MIMEImage (CID) for clients that block data URIs
        logo_path = os.path.join(BASE_DIR, "assets", "club_alpha_logo.png")
        if os.path.exists(logo_path):
            with open(logo_path, "rb") as f_img:
                img_part = MIMEImage(f_img.read())
                img_part.add_header("Content-ID", "<club_alpha_logo>")
                img_part.add_header("Content-Disposition", "inline", filename="club_alpha_logo.png")
                msg.attach(img_part)

        smtp_server = config.get("smtp_server", "smtp.gmail.com")
        smtp_port = config.get("smtp_port", 587)

        server = smtplib.SMTP(smtp_server, smtp_port, timeout=15)
        if config.get("use_tls", True):
            server.starttls()
        server.login(sender, password)
        server.sendmail(sender, all_recipients, msg.as_string())
        server.quit()

        log_entry["status"] = "SENT_SUCCESS"
        write_log(log_entry)
        print(f"[OK] Email reel envoye a {all_recipients} via {smtp_server}:{smtp_port}")
        return {
            "success": True,
            "mode": "real_smtp",
            "message": f"E-mail reel transmis avec succes a {', '.join(all_recipients)}",
            "subject": subject,
            "nb_churn": nb,
            "timestamp": log_entry["timestamp"]
        }
    except Exception as e:
        log_entry["status"] = f"ERROR: {str(e)}"
        write_log(log_entry)
        print(f"[ERROR] Echec de l'envoi SMTP : {e}")
        return {
            "success": False,
            "mode": "smtp_error",
            "error": str(e),
            "message": f"Erreur de connexion SMTP : {e}"
        }

def write_log(entry):
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except Exception as e:
        print(f"[WARN] Erreur ecriture log: {e}")

if __name__ == "__main__":
    print("Test d'execution unitaire du script send_monday_report.py...")
    res = send_monday_email()
    print("Resultat :", json.dumps(res, indent=2, ensure_ascii=False))
